// Generated by scripts/sync-help.mjs from pzza-code-web/components/docs/workspace/SpacingShot.tsx. Regenerate with `npm run sync:help` rather than editing.
/**
 * Spacing at work: a window at the app's narrowest, two tiles stacked in it,
 * while the Spacing setting goes from its default to 0, out to 24 px and
 * back. The setting is the app's own row and Slider (AppearanceSection in src/panels/SettingsMenu.tsx,
 * src/ui/Slider.tsx), shown on a small panel over the grid as the scene's
 * readout; in the app it lives in Settings → General → Appearance. The grid
 * takes the value the way ThemeProvider applies it (--space and data-space on
 * the root), and a value settles like the store's normalizeSpacing
 * (src/state/store.ts). The slider works; a press or key in the scene stops
 * the loop and leaves it to the visitor.
 */
import {
  useId,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
} from "react";
import { SCENE_ROOT, Shot } from "../../home/Chrome";
import { ActiveCanvas } from "../../home/Interactive";
import { AppWindow, SessionTile } from "../../home/Scenes";
import {
  useScenePlayback,
  useVisitorTakeover,
  type Wait,
} from "../../home/playback";
import { WindowLayer } from "./parts";

// SPACING_RANGE in src/state/store.ts.
const SPACING_RANGE = {
  min: 0,
  max: 24,
  default: 10,
  joined: 0,
  smallestGap: 4,
} as const;

/** normalizeSpacing: whole pixels in range; 1 to 3 settle on 0 or 4 so borders never double up. */
function normalizeSpacing(value: number): number {
  const rounded = Math.round(
    Math.min(SPACING_RANGE.max, Math.max(SPACING_RANGE.min, value)),
  );
  if (rounded > SPACING_RANGE.joined && rounded < SPACING_RANGE.smallestGap)
    return rounded < SPACING_RANGE.smallestGap / 2
      ? SPACING_RANGE.joined
      : SPACING_RANGE.smallestGap;
  return rounded;
}

/** SettingsMenu's Row. */
function Row({
  label,
  hint,
  children,
}: {
  label: ReactNode;
  hint?: string;
  children: ReactNode;
}) {
  return (
    <div className="set-row">
      <div className="set-label">
        <span>{label}</span>
        {hint ? <span className="set-hint">{hint}</span> : null}
      </div>
      <div className="set-control">{children}</div>
    </div>
  );
}

/** The app's Slider with the default marked on the track. */
function Slider({
  label,
  min,
  max,
  unit,
  value,
  snap,
  onChange,
}: {
  label: string;
  min: number;
  max: number;
  unit: string;
  value: number;
  snap: { value: number; within: number };
  onChange: (value: number) => void;
}) {
  const marks = useId();
  const shown = `${value}${unit}`;
  const settle = (next: number) =>
    Math.abs(next - snap.value) <= snap.within ? snap.value : next;
  const ratio = (at: number) => (at - min) / Math.max(1, max - min);
  const track = {
    "--fill": `${ratio(value) * 100}%`,
    "--mark-ratio": String(ratio(snap.value)),
  } as CSSProperties;
  return (
    <span className="set-slider">
      <span className="set-slider-track" style={track}>
        <input
          aria-label={label}
          type="range"
          min={min}
          max={max}
          step={1}
          value={value}
          list={marks}
          aria-valuetext={shown}
          onChange={(event) => onChange(settle(Number(event.target.value)))}
        />
        <span
          className={`set-slider-mark ${value === snap.value ? "is-on" : ""}`}
          title="Default"
          aria-hidden="true"
        />
      </span>
      <datalist id={marks}>
        <option value={snap.value} label="Default" />
      </datalist>
      <output className="set-slider-value" aria-hidden="true">
        {shown}
      </output>
    </span>
  );
}

// The loop: the default, then a drag down to 0, out to 24 and back to the mark.
const HOLD_MS = 2200;
const STEP_MS = 45;
const STOPS = [SPACING_RANGE.joined, SPACING_RANGE.max, SPACING_RANGE.default];

/* The window at the app's minimum width (720, tauri.conf.json), where its
   Auto layout stacks two sessions in one column (tiles sharing a row stay at
   least 360px wide, src/grid/autoLayout.ts), and tall enough that each row
   keeps its 300px minimum at 24px. The card shows the window from under its
   top bar to below its bottom edge, so the spacing shows all around the
   tiles and between them, and no edge ever cuts a tile however it moves.
   The captures are 65 columns, which fit the terminals at every spacing. */
const WINDOW = { width: 720, height: 720 };
const MARGIN = 16;
const TOP_BAR = 42;
const PANEL_WIDTH = 330;
// .menu-panel's 14px padding around one 32px settings row, plus its border.
const PANEL_HEIGHT = 62;

export function SpacingShot() {
  const [spacing, setSpacing] = useState<number>(SPACING_RANGE.default);
  const root = useRef<HTMLDivElement>(null);
  const handedOver = useVisitorTakeover(root);
  useScenePlayback(
    root,
    async (wait: Wait) => {
      let value: number = SPACING_RANGE.default;
      for (const stop of STOPS) {
        await wait(HOLD_MS);
        // The thumb passes every pixel on its way, as a drag does.
        while (value !== stop) {
          value += Math.sign(stop - value);
          const shown = normalizeSpacing(value);
          setSpacing(
            Math.abs(shown - SPACING_RANGE.default) <= 1
              ? SPACING_RANGE.default
              : shown,
          );
          await wait(STEP_MS);
        }
        setSpacing(stop);
      }
    },
    { stopped: handedOver },
  );
  const box = { left: MARGIN, top: -TOP_BAR, ...WINDOW };
  // The readout sits centred near the bottom of the window, in window coordinates.
  const panel: CSSProperties = {
    left: (WINDOW.width - PANEL_WIDTH) / 2,
    top: WINDOW.height - 28 - PANEL_HEIGHT,
    right: "auto",
    width: PANEL_WIDTH,
  };
  return (
    <Shot id="usage" width={WINDOW.width + MARGIN * 2} height={WINDOW.height - TOP_BAR + MARGIN}>
      {/* The root's spacing, as ThemeProvider sets it on <html>. */}
      <div
        ref={root}
        className="pz"
        {...SCENE_ROOT}
        data-space={String(spacing)}
        style={
          {
            position: "absolute",
            inset: 0,
            "--space": `${spacing}px`,
          } as CSSProperties
        }
      >
        <AppWindow box={box}>
          <ActiveCanvas
            style={{ gridTemplateRows: "1fr 1fr" }}
            tiles={[
              <SessionTile key="api" id="api" capture="api-65" kbd="⌘1" />,
              <SessionTile key="web" id="web" capture="web-65" kbd="⌘2" />,
            ]}
          />
          <WindowLayer>
            <div className="menu menu-panel" style={panel}>
              <Row label="Spacing">
                <Slider
                  label="Spacing"
                  min={SPACING_RANGE.min}
                  max={SPACING_RANGE.max}
                  unit="px"
                  value={spacing}
                  snap={{ value: SPACING_RANGE.default, within: 1 }}
                  onChange={(value) => setSpacing(normalizeSpacing(value))}
                />
              </Row>
            </div>
          </WindowLayer>
        </AppWindow>
      </div>
    </Shot>
  );
}
